import React from 'react';

import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';
import PohLoader, { LoaderVariant } from '@ui-kit/Loader';

import { ISearchObstacleCriteria, searchObstacleAsync } from '../../@services/obstacles.service';
import { IObstacle } from '../../@types/obstacles.types';
import ObstacleListItem from '../ObstaclesByTypePage/ObstacleListItem';

interface IObstacleSelectModalProps {
  criteria?: ISearchObstacleCriteria;
  onChange: (obstacle: IObstacle) => void;
}

const ObstacleSelectModal: React.FC<IObstacleSelectModalProps> = ({ onChange, criteria }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [results, setResults] = React.useState<IObstacle[]>([]);
  const [q, setQ] = React.useState<string>('');

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await searchObstacleAsync({ ...criteria, query: q });
      setResults(res);
    } finally {
      setIsLoading(false);
    }
  }, [criteria]);

  React.useEffect(() => {
    load();
  }, [q, criteria]);

  return (
    <section style={{ width: 800 }}>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          load();
        }}
      >
        <PohInput type={InputTypes.search} required onChange={setQ} value={q} />
      </form>
      <div style={{ overflowY: 'auto', maxHeight: 480 }}>
        {isLoading ? (
          <PohLoader variant={LoaderVariant.Dark} />
        ) : (
          <PohList
            data={results.map((res) => {
              return {
                key: res.id,
                action: true,
                onClick: () => onChange(res),
                children: <ObstacleListItem obstacle={res} />,
                //className:'p-0'
              };
            })}
          />
        )}
      </div>
    </section>
  );
};

export default ObstacleSelectModal;
